import 'package:cached_network_image/cached_network_image.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../../core/theme/app_colors.dart';
import '../../data/services/cctv_service.dart';

/// An image that self-heals when its presigned URL becomes stale.
///
/// Presigned URLs are generated by the backend using its configured storage
/// endpoint. When the server IP changes, those URLs break. This widget
/// catches load errors and fetches a fresh URL from the current API server,
/// so images always show up regardless of which server is connected.
class ResilientImage extends ConsumerStatefulWidget {
  final String? source;
  final String cctvId;
  final double? width;
  final double? height;
  final BoxFit fit;

  const ResilientImage({
    super.key,
    required this.source,
    required this.cctvId,
    this.width,
    this.height,
    this.fit = BoxFit.cover,
  });

  @override
  ConsumerState<ResilientImage> createState() => _ResilientImageState();
}

class _ResilientImageState extends ConsumerState<ResilientImage> {
  String? _currentUrl;
  int _retryCount = 0;
  bool _retrying = false;

  @override
  void initState() {
    super.initState();
    _currentUrl = widget.source;
  }

  @override
  void didUpdateWidget(ResilientImage oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.source != widget.source) {
      _currentUrl = widget.source;
      _retryCount = 0;
    }
  }

  Future<void> _refreshUrl() async {
    if (_retrying || _retryCount >= 3) return;
    _retrying = true;
    _retryCount++;

    try {
      final service = ref.read(cctvServiceProvider);
      final urls = await service.getImageUrls(widget.cctvId);
      if (urls.isNotEmpty && mounted) {
        final freshUrl = urls.values.first;
        if (freshUrl.isNotEmpty) {
          setState(() {
            _currentUrl = freshUrl;
          });
        }
      }
    } catch (_) {
      // Network may be unreachable; will retry on next error
    } finally {
      _retrying = false;
    }
  }

  @override
  Widget build(BuildContext context) {
    final url = _currentUrl;
    if (url == null || url.isEmpty) {
      return _placeholder();
    }

    return CachedNetworkImage(
      key: ValueKey(url),
      imageUrl: url,
      width: widget.width,
      height: widget.height,
      fit: widget.fit,
      placeholder: (context, url) => _placeholder(),
      errorWidget: (context, url, error) {
        // Schedule URL refresh for after this frame completes
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _refreshUrl();
        });
        return _placeholder();
      },
    );
  }

  Widget _placeholder() {
    return Container(
      width: widget.width,
      height: widget.height,
      color: AppColors.surfaceVariant,
      child: Center(
        child: Icon(
          Icons.image_outlined,
          color: AppColors.textTertiary,
          size: (widget.width ?? 72) * 0.3,
        ),
      ),
    );
  }
}
